package io.knowledgebrain.space;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_SPACE_DATABASE_URL",matches=".+")
class PublicKnowledgeAuthorizationIntegrationTest {
    @Test void guestCanBrowseOnlyRegisteredMayProposeAndOnlyActiveReviewerMayReview(){var source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));source.setUser("brain_space");source.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").load().migrate();var jdbc=new JdbcTemplate(source);var store=new PublicKnowledgeSpaces(source);UUID actor=new UuidV7(Clock.systemUTC()).next(),space=UUID.fromString("0199e000-0000-7000-8000-000000000002");var guest=new IdentityPrincipalClient.Principal(actor,"GUEST",Instant.now().plusSeconds(60));var account=new IdentityPrincipalClient.Principal(actor,"REGISTERED",guest.expiresAt());assertThat(store.list(guest)).hasSize(2);store.authorize(space,guest,"PUBLIC_CONCEPT_READ");assertThatThrownBy(()->store.authorize(space,guest,"CONTRIBUTION_PROPOSE")).isInstanceOf(ResponseStatusException.class);store.authorize(space,account,"CONTRIBUTION_PROPOSE");assertThatThrownBy(()->store.authorize(space,account,"CONTRIBUTION_REVIEW")).isInstanceOf(ResponseStatusException.class);jdbc.update("INSERT INTO space_membership(space_id,principal_id,role) VALUES (?,?,'REVIEWER')",space,actor);try{store.authorize(space,account,"CONTRIBUTION_REVIEW");store.authorize(space,account,"CONTRIBUTION_MERGE");assertThatThrownBy(()->store.authorize(space,guest,"CONTRIBUTION_REVIEW")).isInstanceOf(ResponseStatusException.class);jdbc.update("UPDATE space_membership SET state='RETIRED' WHERE space_id=? AND principal_id=?",space,actor);assertThatThrownBy(()->store.authorize(space,account,"CONTRIBUTION_MERGE")).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.authorize(new UuidV7(Clock.systemUTC()).next(),account,"PUBLIC_CONCEPT_READ")).isInstanceOf(ResponseStatusException.class);}finally{jdbc.update("DELETE FROM space_membership WHERE space_id=? AND principal_id=?",space,actor);}}
    @Test void publicQueryActionsRecheckIdentityAndRejectNonPublicSpaces(){var source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));source.setUser("brain_space");source.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));var personal=org.mockito.Mockito.mock(PersonalSpaceStore.class);var identity=org.mockito.Mockito.mock(IdentityPrincipalClient.class);var actor=new UuidV7(Clock.systemUTC()).next();var api=new QueryAuthorizationController(personal,identity,"k".repeat(43));api.dataSource=source;var request=new org.springframework.mock.web.MockHttpServletRequest();request.setSecure(true);request.addHeader("Authorization","Bearer "+"k".repeat(43));org.mockito.Mockito.when(identity.resolve("a".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,"GUEST",Instant.now().plusSeconds(60)));var space=UUID.fromString("0199e000-0000-7000-8000-000000000002");for(String action:List.of("PUBLIC_SEARCH","PUBLIC_GRAPH")){var decision=api.authorize(new QueryAuthorizationController.Check(space,"a".repeat(43),action),request).getBody();assertThat(decision.visibility()).isEqualTo("PUBLIC");assertThat(decision.action()).isEqualTo(action);assertThat(decision.principalId()).isEqualTo(actor);}assertThatThrownBy(()->api.authorize(new QueryAuthorizationController.Check(new UuidV7(Clock.systemUTC()).next(),"a".repeat(43),"PUBLIC_GRAPH"),request)).isInstanceOf(ResponseStatusException.class);org.mockito.Mockito.verifyNoInteractions(personal);org.mockito.Mockito.verify(identity,org.mockito.Mockito.times(3)).resolve("a".repeat(43),null);}

}
